gap0(){return"\u062a\u064f\u0646\u0642\u0644 \u0627\u0644\u0643\u0631\u0629 \u0628\u062a\u0645\u0631\u064a\u0631\u0627\u062a \u0642\u0635\u064a\u0631\u0629. \u0648\u0644\u0627 \u062a\u0623\u062a\u064a \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0637\u0648\u064a\u0644\u0629 \u0625\u0644\u0627 \u062d\u064a\u0646 \u062a\u0646\u0639\u062f\u0645 \u0627\u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0623\u062e\u0631\u0649."},
gaoZ(){return"\u062a\u064f\u0631\u0633\u0644 \u0627\u0644\u0643\u0631\u0629 \u0633\u0631\u064a\u0639\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u062f\u0648\u0646 \u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0645\u0631\u064a\u0631\u0629 \u0628\u064a\u0646\u064a\u0629."},
gaoR(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0623\u0645\u0627\u0645 \u0645\u0646\u0637\u0642\u0629 \u062c\u0632\u0627\u0626\u0647. \u0644\u0627 \u062a\u0628\u0642\u0649 \u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647."},
gaoS(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u062a\u064f\u062a\u0631\u0643 \u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u064a \u0623\u0645\u0627\u0645\u0647 \u0644\u0644\u062e\u0635\u0645."},
gaoT(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0646\u0635\u0641 \u0645\u0644\u0639\u0628\u0647\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u0627\u0644\u062d\u0627\u0631\u0633 \u0645\u063a\u0644\u0642\u0629."},
gaoU(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0648\u0633\u0637 \u0627\u0644\u0645\u0644\u0639\u0628. \u0648\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647 \u0648\u0627\u0633\u0639\u0629."},
gaoV(){return"\u064a\u062a\u062c\u0627\u0648\u0632 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u0645\u0644\u0639\u0628. \u0648\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u062d\u0627\u0631\u0633 \u0648\u062d\u062f\u0647."},
gap4(){return"\u064a\u062a\u062c\u0645\u0639 \u0627\u0644\u062c\u0645\u064a\u0639 \u0641\u064a \u0627\u0644\u0639\u0645\u0642\u060c \u0648\u062a\u0628\u0642\u0649 \u0627\u0644\u0623\u062c\u0646\u062d\u0629 \u0641\u0627\u0631\u063a\u0629."},
gap5(){return"\u064a\u064f\u0628\u0646\u0649 \u0627\u0644\u0644\u0639\u0628 \u0645\u0646 \u0627\u0644\u062f\u0627\u062e\u0644\u060c \u0648\u0646\u0627\u062f\u0631\u064b\u0627 \u0645\u0627 \u062a\u062a\u062c\u0647 \u0627\u0644\u0643\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0637\u0631\u0627\u0641."},
gap6(){return"\u0644\u0627 \u064a\u0644\u062a\u0635\u0642 \u0627\u0644\u062c\u0646\u0627\u062d\u0627\u0646 \u0628\u0627\u0644\u062e\u0637\u060c \u0628\u0644 \u064a\u0644\u0639\u0628\u0627\u0646 \u0641\u064a \u0627\u0644\u062f\u0627\u062e\u0644. \u0648\u0633\u0637 \u0627\u0644\u0645\u0644\u0639\u0628 \u0645\u0632\u062f\u062d\u0645."},
